/**
 * Constants that can be used to force an error state in a bridge transaction.
 * Typically used for the LocalChainBridge which currently accepts all messages
 * unless specified otherwise. Less useful for the DibcBridge which rejects all
 * messages unless specified otherwise.
 */
export const SIMULATED_ERRORS = /** @type {const} */ ({
  TIMEOUT: 504n,
  BAD_REQUEST: 400n,
});

/**
 * Used to mock responses from Cosmos Golang back to SwingSet for for
 * E(lca).executeTx().
 *
 * Returns an empty object per message unless specified.
 *
 * @param {object} message
 * @param {number} sequence
 * @returns {unknown}
 * @throws {Error} to simulate failures in certain cases
 */
export const fakeLocalChainBridgeTxMsgHandler = (message, sequence) => {
  switch (message['@type']) {
    // TODO #9402 reference bank to ensure caller has tokens they are transferring
    case '/ibc.applications.transfer.v1.MsgTransfer': {
      /**
       * This call should always resolve with a sequence number unless the
       * message is rejected by the local chain (malformed, unauthorized, etc).
       * This sequence number is wrt to the channel (not the account) and
       * indicates an outgoing IBC transfer has _started_ but doesn't mean it
       * has been acknowledged by the remote chain.
       *
       * If you are testing `MsgTransfer` with a `LocalOrchestrationAccount`,
       * you must inbound a `VTRANSFER_IBC_EVENT` to the `vtransfer` bridge with
       * an acknowledgement, acknowledgement error, or timeout. See
       * `buildVTransferEvent`, `transmitTransferTimeout`, `transmitTransferAck`
       * and `transmitTransferAckError` for examples.
       */
      // like `JsonSafe<MsgTransferResponse>`, but bigints are converted to numbers
      // FIXME should vlocalchain return a string instead of number for bigint?
      return {
        sequence,
      };
    }
    case '/cosmos.bank.v1beta1.MsgSend': {
      if (message.amount[0].amount === String(SIMULATED_ERRORS.BAD_REQUEST)) {
        throw Error('simulated error');
      }
      return /** @type {JsonSafe<MsgSendResponse>} */ ({});
    }
    case '/cosmos.staking.v1beta1.MsgDelegate': {
      if (message.amount.amount === String(SIMULATED_ERRORS.TIMEOUT)) {
        throw Error('simulated packet timeout');
      }
      return /** @type {JsonSafe<MsgDelegateResponse>} */ ({});
    }
    case '/cosmos.staking.v1beta1.MsgUndelegate': {
      return /** @type {JsonSafe<MsgUndelegateResponse>} */ ({
        // 5 seconds from unix epoch
        completionTime: { seconds: '5', nanos: 0 },
      });
    }
    // returns one empty object per message unless specified
    default:
      return {};
  }
};
  };

  /** @type {Bank} */
  const bank = Far('mock bank', {
    /** @param {Brand} brand */
    getPurse: async brand => purses.get(brand),
    getAssetSubscription: () => subscription,
  });

  return { addAsset, assetPublication: publication, bank };
};

/**
 * @param {object} [opts]
 * @param {Balances} [opts.balances] initial balances
 * @param {(obj) => unknown} [opts.onToBridge] handler for toBridge messages
 */
export const makeFakeBankManagerKit = async opts => {
  const baggage = makeScalarBigMapStore('baggage');
  const zone = makeDurableZone(baggage);

  const bankManager = await buildBankVatRoot(
    undefined,
    undefined,
    zone.mapStore('bankManager'),
  ).makeBankManager(makeFakeBankBridge(zone, opts));

  /**
   * Get a payment from the faucet
   *
   * @param {Amount<'nat'>} amount
   * @returns {Promise<Payment<'nat'>>}
   */
  const pourPayment = async amount => {
    const faucet = await E(bankManager).getBankForAddress(FAUCET_ADDRESS);
    const purse = await E(faucet).getPurse(amount.brand);
    return E(purse).withdraw(amount);
  };

  return { bankManager, pourPayment };
};
/**
 * @import {ChainHub, ChainInfo, Denom, DenomDetail} from '../types.js';
 * @import {Brand} from '@agoric/ertp';
 */

/**
 * Registers chains, connections, assets in the provided chainHub.
 *
 * If either is not provided, registration will be skipped.
 *
 * TODO #10580 remove 'brandKey' in favor of `LegibleCapData`
 *
 * @param {ChainHub} chainHub
 * @param {Record<string, Brand<'nat'>>} brands
 * @param {Record<string, ChainInfo> | undefined} chainInfo
 * @param {[Denom, DenomDetail & { brandKey?: string }][] | undefined} assetInfo
 * @param {object} opts
 * @param {Console['log']} [opts.log]
 */
export const registerChainsAndAssets = (
  chainHub,
  brands,
  chainInfo,
  assetInfo,
  { log = () => {} } = {},
) => {
  log('chainHub: registering chains', Object.keys(chainInfo || {}));
  if (!chainInfo) {
    return;
  }

  const conns = {};
  for (const [chainName, allInfo] of Object.entries(chainInfo)) {
    if (allInfo.namespace === 'cosmos') {
      const { connections, ...info } = allInfo;
      chainHub.registerChain(chainName, info);
      if (connections) conns[info.chainId] = connections;
    } else {
      chainHub.registerChain(chainName, allInfo);
    }
  }
  const registeredPairs = new Set();
  for (const [pChainId, connInfos] of Object.entries(conns)) {
    for (const [cChainId, connInfo] of Object.entries(connInfos)) {
      const pair = [pChainId, cChainId].sort().join('<->');
      if (!registeredPairs.has(pair)) {
        chainHub.registerConnection(pChainId, cChainId, connInfo);
        registeredPairs.add(pair);
      }
    }
  }
  log('chainHub: registered connections', [...registeredPairs].sort());

  log(
    'chainHub: registering assets',
    assetInfo?.map(([denom, { chainName }]) => `${chainName}: ${denom}`),
  );
  if (!assetInfo) {
    return;
  }
  for (const [denom, info] of assetInfo) {
    const { brandKey, ...rest } = info;
    const infoWithBrand = brandKey
      ? { ...rest, brand: brands[brandKey] }
      : rest;
    chainHub.registerAsset(denom, infoWithBrand);
  }
};
